package br.com.admeclesial.interfaces.rest.matrimonio; import br.com.admeclesial.application.matrimonio.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/processos-matrimoniais") public class ProcessoMatrimonialRestController { final ProcessoMatrimonialApplicationService s; public ProcessoMatrimonialRestController(ProcessoMatrimonialApplicationService s){this.s=s;} @PostMapping public ResponseEntity<ProcessoMatrimonialResponse> criar(@Valid @RequestBody ProcessoMatrimonialRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.criar(r));} @PutMapping("/{uuid}") public ProcessoMatrimonialResponse atualizar(@PathVariable UUID uuid,@Valid @RequestBody ProcessoMatrimonialRequest r){return s.atualizar(uuid,r);} @GetMapping public List<ProcessoMatrimonialResponse> listar(){return s.listar();} @GetMapping("/{uuid}") public ProcessoMatrimonialResponse buscar(@PathVariable UUID uuid){return s.buscar(uuid);} }